import fsp from 'node:fs/promises';
import path from 'node:path';
import { PLAN_TEXT_MAX, ResumeError, SETTLED_RUN, answerRun, badRequest, emitChanged, invokeStartRun, liveRunEntry, pauseRun, postDirection, prWatcherDeps, projectDirForKey, resumeRun, runs, startRunHandler, stopPausedPipeline, stopRun } from '../../server.mjs';

/** Restart Build (Stillhet): the brief of a run that builds a stopped or failed task's saved plan on its kept branch. */
const restartBrief = (plan, feature) => [
  `Restart the Build of this task from its approved plan below, on its kept branch \`${feature}\`.`,
  'The branch already holds the earlier attempt\'s commits: keep what is right, finish the rest, and run the tests.',
  '', plan].join('\n');
const restartRefusal = (res, status, code, error) => res.status(status).json({ error, code });
/** Pause after this step (Stillhet): the run keeps going until no step is in flight, then pauses as pauseRun does. */
function pauseAfterStepRun(runId, by = 'local') {
  const entry = runs.get(runId);
  const ok = typeof entry?.orch?.pauseAfterStep === 'function' ? entry.orch.pauseAfterStep(by || 'local') : false;
  if (ok === 'already') throw Object.assign(new Error('a pause after this step is already on its way'), { code: 'ALREADY_PAUSING' });
  if (!ok) throw Object.assign(new Error('cannot pause in the current state'), { code: 'CANNOT_PAUSE' });
  entry.lastAction = { kind: 'pause', by: by || 'local', at: new Date().toISOString() };
}
/** Restart Build presses in flight, by round origin: a second press answers RESTART_BUSY until the first has started. */
const restarting = new Set();
const mockOfRow = (row) => { try { return JSON.parse(row.resume_point || 'null')?.mock === true; } catch { return false; } };

export function register(app) {
app.post('/api/run', startRunHandler);

// POST /api/runs/:id/restart-build (id = the pipeline id) -> { runId, pipelineId }: a stopped or failed task's Build again,
// as a new round on its kept branch (plans/rail/task-engine-additions.md). A paused task resumes instead (POST /api/resume).
app.post('/api/runs/:id/restart-build', async (req, res) => {
  let lock = null;
  try {
    const row = findPipelineRowById(req.params.id);
    if (!row || row.archived_at) return res.status(404).json({ error: 'pipeline not found' });
    if (row.status !== 'stopped' && row.status !== 'error') {
      return restartRefusal(res, 409, 'NOT_STOPPED', 'Only a stopped or failed task can restart Build; a paused one resumes.');
    }
    if (row.target === 'workspace' || row.workspace_key) {
      return restartRefusal(res, 409, 'WORKSPACE', 'Restart Build is not offered for a workspace task yet.');
    }
    // One restart per task at a time: reserved before the first await, released once the run has started (or refused).
    const origin = roundOrigin(row.id);
    if (restarting.has(origin)) return restartRefusal(res, 409, 'RESTART_BUSY', 'Build is already restarting for this task.');
    restarting.add(origin); lock = origin;
    const planArt = (await listArtifacts(row.id)).filter((a) => a.kind === 'plan').at(-1);
    const plan = planArt ? await resolveIndexedArtifactForRow(row, planArt.relPath) : null;
    if (!plan?.text?.trim()) return restartRefusal(res, 409, 'NO_PLAN', 'This task has no saved plan to build from.');
    let branch = null; try { branch = JSON.parse(row.branch || 'null'); } catch { /* none */ }
    const projectDir = await projectDirForKey(row.project_key);
    if (!projectDir || !branch?.feature || !(await branchExists(projectDir, branch.feature))) {
      return restartRefusal(res, 409, 'NO_BRANCH', 'This task\'s branch is gone, so Build cannot restart on it.');
    }
    // A run already on the branch (an earlier restart round, a PR fix run) holds it: a second start would fight over it.
    if (prWatcherDeps.liveOnBranch({ projectDir, branch: branch.feature })) {   // dev's rule: live, paused, finishing, or a terminal resolve
      return restartRefusal(res, 409, 'BUSY', 'Another run is working on this task\'s branch; wait for it to finish.');
    }
    const tags = readRunTags(row.id); const labels = readRunLabels(row.id);
    const body = {
      projectDir,
      title: `Restart Build: ${row.title || branch.feature}`.slice(0, 200),
      prompt: restartBrief(plan.text, branch.feature),
      workflowId: FIX_WORKFLOW_ID,
      humanInLoop: false,
      ...(branch.source ? { sourceBranch: branch.source } : {}),
      featureBranch: branch.feature,
      syncBeforeStart: false,
      ...(row.guardrails_id ? { guardrailsId: row.guardrails_id } : {}),
      engine: runEngineOfRow(row),
      ...(mockOfRow(row) ? { mock: true } : {}),
      ...(tags.length ? { tags } : {}),
      ...(labels.length ? { labels } : {}),
    };
    const by = actorOf(req);
    const out = await invokeStartRun(body, null, { startedBy: by, runCostCapUsd: readRunCostCap(row.id),
      roundOf: { pipelineId: origin, round: nextRound(origin), request: 'restart Build', by: 'restart' } });
    if (out.status !== 200 || !out.body?.runId) return res.status(out.status === 200 ? 500 : out.status).json(out.body || { error: 'the run did not start' });
    appendAuditById(row.id, `Restarted Build on \`${branch.feature}\` as a new round${byActor(by)}.`, { actor: by });
    emitChanged('pipelines-changed', 'updated');
    res.json({ runId: out.body.runId, pipelineId: runs.get(out.body.runId)?.pipelineId || null });
  } catch (err) { if (!res.headersSent) res.status(500).json({ error: err?.message || String(err) }); }
  finally { if (lock) restarting.delete(lock); }
});

// ---------------------------------------------------------------------------
// POST /api/answer  -> resolve a pending question for a run
// body: { runId, id, payload }
// ---------------------------------------------------------------------------
app.post('/api/answer', (req, res) => {
  const { runId, id, payload } = req.body || {};
  if (!runId || !runs.has(runId)) return badRequest(res, 'unknown runId');
  if (!id) return badRequest(res, 'question id is required');
  try {
    answerRun(runId, id, payload, actorOf(req));
    res.json({ ok: true });
  } catch (err) {
    // Gate 3 (ask forms, spec §5): the answer was validated and refused, so the
    // question stays OPEN and the client gets the field errors to mark up. Every
    // other failure keeps its 500.
    if (err && err.code === 'INVALID_ANSWER') {
      return res.status(422).json({ error: 'invalid answer', errors: Array.isArray(err.errors) ? err.errors : [] });
    }
    res.status(500).json({ error: err && err.message ? err.message : String(err) });
  }
});

// POST /api/runs/:id/answer  -> answer the run's plan approval stop (shape-it-first D2/D10)
// body: { id, decision: 'approve'|'revise'|'stop', feedback?, source?, conflicts?, decisions? } (the picks validatePlanAnswer checks).
app.post('/api/runs/:id/answer', (req, res) => {
  const runId = req.params.id;
  const entry = runs.get(runId);
  if (!entry) return res.status(404).json({ error: 'unknown run' });
  const { id, decision, feedback, perspectives, edits, approveEach, source, conflicts, decisions } = req.body || {};
  const pq = entry.pendingQuestion;
  if (!pq || pq.kind !== PLAN_ASK_KIND || !id || pq.id !== id) {
    return res.status(409).json({ error: 'no plan approval with that id is waiting on this run' });
  }
  try {
    answerRun(runId, id, { decision, ...(feedback !== undefined ? { feedback } : {}),
      ...(perspectives !== undefined ? { perspectives } : {}),
      ...(edits !== undefined ? { edits } : {}),
      ...(approveEach !== undefined ? { approveEach } : {}),
      ...(source !== undefined ? { source } : {}),
      ...(conflicts !== undefined ? { conflicts } : {}),
      ...(decisions !== undefined ? { decisions } : {}) }, actorOf(req));
    res.json({ ok: true });
  } catch (err) {
    if (err && err.code === 'INVALID_ANSWER') {
      return res.status(422).json({ error: 'invalid answer', errors: Array.isArray(err.errors) ? err.errors : [] });
    }
    res.status(500).json({ error: err && err.message ? err.message : String(err) });
  }
});

// The plan card's text (S4/S6): the open plan ask's file, the approved one, or ?round=N's. The path is the server's own.
app.get('/api/runs/:id/plan', async (req, res) => {
  const entry = runs.get(req.params.id);
  if (!entry) return res.status(404).json({ error: 'unknown run' });
  const file = planFileOf({ pendingQuestion: entry.pendingQuestion, shaping: entry.orch?.state?.shaping }, req.query.round);
  if (!file) return res.status(404).json({ error: 'no plan on this run' });
  try {
    const text = await fsp.readFile(file, 'utf8');
    const truncated = text.length > PLAN_TEXT_MAX;
    res.json({ file, name: path.basename(file), text: truncated ? text.slice(0, PLAN_TEXT_MAX) : text, truncated });
  } catch {
    res.status(404).json({ error: 'plan file not found' });
  }
});

// Save to plans/ (D10, S7): into the registered checkout, never over a file without {overwrite:true}, never a commit.
app.post('/api/runs/:id/plan/save', async (req, res) => {
  const entry = runs.get(req.params.id);
  if (!entry) return res.status(404).json({ error: 'unknown run' });
  if (entry.workspaceId || !entry.projectDir) return res.status(409).json({ error: 'Save to plans/ needs a single-project run' });
  const file = planFileOf({ pendingQuestion: entry.pendingQuestion, shaping: entry.orch?.state?.shaping });
  if (!file) return res.status(404).json({ error: 'no plan on this run' });
  try {
    const r = await savePlanToCheckout({ file, projectDir: entry.projectDir, title: entry.title, overwrite: req.body?.overwrite === true });
    if (!r.ok) return res.status(r.status).json({ error: r.error, ...(r.path ? { path: r.path } : {}) });
    entry.orch?.recordPlanSaved?.(r.path);
    res.json({ ok: true, path: r.path });
  } catch (err) {
    res.status(500).json({ error: err && err.message ? err.message : String(err) });
  }
});

// ---------------------------------------------------------------------------
// POST /api/stop  -> abort a live run, or stop a paused one for good
// body: { runId } | { pipelineId } | { runId, pipelineId }
// A known runId acts on that entry (stopRun routes a paused one to stopPausedPipeline).
// A pipelineId alone — or with a runId this server does not know (a tab from before a
// restart) — stops the paused run from its saved row.
// ---------------------------------------------------------------------------
app.post('/api/stop', async (req, res) => {
  const { runId, pipelineId } = req.body || {};
  try {
    if (runId && runs.has(runId)) return res.json(await stopRun(runId, actorOf(req)));
    if (pipelineId && typeof pipelineId === 'string') {
      // A tab from before a restart may still show the run paused while this server already
      // resumed it: stop the run that is live now, rather than refusing a stale runId.
      const live = liveRunEntry(pipelineId);
      if (live && !SETTLED_RUN.has(String(live.status || ''))) return res.json(await stopRun(live.id, actorOf(req)));
      return res.json(await stopPausedPipeline(pipelineId, actorOf(req)));
    }
    return badRequest(res, 'unknown runId');
  } catch (err) {
    if (err instanceof StopPausedError) return res.status(err.status).json({ error: err.message, code: err.code });
    res.status(500).json({ error: err && err.message ? err.message : String(err) });
  }
});

// ---------------------------------------------------------------------------
// POST /api/pause { runId } — gracefully pause a LIVE run. The orchestrator kills
// in-flight node children, persists a resume point, and lands on status 'paused'
// (announced via the normal state/done events; wireRun mirrors entry.status).
// ---------------------------------------------------------------------------
// ---------------------------------------------------------------------------
// POST /api/run/night { runId, mode: 'auto'|'on'|'off' } — the run-view night mode switch.
// A paused run stores it in its resume point; a finished run refuses it (400).
// ---------------------------------------------------------------------------
function setRunNightMode(runId, mode, by = 'local') {
  const entry = runs.get(runId);
  if (!entry) throw new Error('unknown runId');
  if (typeof entry.orch?.setNightOverride !== 'function') throw Object.assign(new Error('run does not support Away mode'), { code: 'BAD_NIGHT_MODE' });
  entry.orch.setNightOverride(mode, by || 'local');
}
app.post('/api/run/night', (req, res) => {
  const { runId, mode } = req.body || {};
  if (!runId || !runs.has(runId)) return badRequest(res, 'unknown runId');
  try {
    setRunNightMode(runId, mode, actorOf(req));
    res.json({ ok: true });
  } catch (err) {
    if (err?.code === 'BAD_NIGHT_MODE' || err?.code === 'NIGHT_NOT_LIVE') return badRequest(res, err.message);
    res.status(500).json({ error: err && err.message ? err.message : String(err) });
  }
});

// GET /api/night-decisions?pipelineId=… | ?runId=… — what night mode decided on one run.
app.get('/api/night-decisions', (req, res) => {
  const pipelineId = String(req.query.pipelineId || '') || runs.get(String(req.query.runId || ''))?.orch?.pipeline?.id;
  if (!pipelineId) return badRequest(res, 'pipelineId or runId required');
  res.json({ decisions: readNightDecisions(pipelineId) });
});

// GET /api/away-mode[?projectDir=] — what Away mode will do: the effective config (with the team
// layer when a project is given), where each field comes from, what an empty field falls back to,
// the live status (toggle, and hereSince: when "I'm here" was last said) and the raw layers the forms edit. Every surface renders its text from this
// through src/shared/away-mode/describe.mjs.
// The run engines and whether each is ready now (engines/readiness.mjs: the adapter's own preflight, cached 60 s).
// ?recheck=1 forces a fresh check. Feeds the usage-limit "continue on…" offers and the engine cards.
// Which engines this instance never starts (the credential broker is on): cheap, no preflight — every page asks once.
app.get('/api/engine-locks', (req, res) => res.json({ engines: engineLocks() }));

app.post('/api/pause', (req, res) => {
  const { runId, afterStep } = req.body || {};
  if (!runId || !runs.has(runId)) return badRequest(res, 'unknown runId');
  try {
    if (afterStep === true) pauseAfterStepRun(runId, actorOf(req));   // Pause after this step (Stillhet)
    else pauseRun(runId, actorOf(req));
    res.json({ ok: true });
  } catch (err) {
    if (err?.code === 'ALREADY_PAUSING') return res.status(409).json({ error: 'A pause after this step is already on its way.', code: 'ALREADY_PAUSING' });
    // `status`: what the run is instead, so a tab whose click lost to another pause keeps its Pausing… quietly.
    if (err?.code === 'CANNOT_PAUSE') return res.status(400).json({ error: err.message, code: 'CANNOT_PAUSE', status: runs.get(runId)?.status || null });
    res.status(500).json({ error: err && err.message ? err.message : String(err) });
  }
});

// ---------------------------------------------------------------------------
// POST /api/resume { pipelineId, engine?, allowUnguardedEngine? } — rehydrate a paused pipeline from the DB (works
// across server restarts) and continue it as a NEW live run entry with the SAME
// pipeline id / history row.
// ---------------------------------------------------------------------------
app.post('/api/resume', async (req, res) => {
  try {
    const out = await resumeRun(req.body?.pipelineId, {
      ignoreCostCap: req.body?.ignoreCostCap === true,
      mock: !!(req.body && req.body.mock),
      pastTeamCap: req.body?.pastTeamCap === true,
      policyReason: typeof req.body?.policyReason === 'string' ? req.body.policyReason : null,
      by: actorOf(req),
      baseCheck: req.body?.baseCheck === true,
      baseAck: req.body?.baseAck === true,
      engine: req.body?.engine,
      allowUnguardedEngine: req.body?.allowUnguardedEngine,
      model: req.body?.model,
      effort: req.body?.effort,
      costCapUsd: req.body?.costCapUsd,
    });
    res.json(out);
  } catch (err) {
    // The engine gate's refusal is the run's CLI wording; this answer is the UI's.
    if (err instanceof ResumeError) return res.status(err.status).json(err.body.code === 'engine-refused' ? { ...err.body, error: engineRefusalFor(err.body.error, 'ui') } : err.body);
    res.status(500).json({ error: err && err.message ? err.message : String(err) });
  }
});

app.post('/api/runs/:id/directions', async (req, res) => {
  const { text } = req.body || {};
  if (text === undefined || text === null || text === '') return badRequest(res, 'text is required');
  if (typeof text !== 'string') return badRequest(res, 'text must be a string');
  // Whitespace-only is a bad request, not a server error: appendDirection throws
  // EMPTY_DIRECTION on it, which the generic catch below would turn into a 500.
  // Same guard the ask route uses.
  if (!text.trim()) return badRequest(res, 'text is required');
  if (text.length > DIRECTION_MAX_CHARS) return badRequest(res, `text must be at most ${DIRECTION_MAX_CHARS} characters`);
  try {
    const rec = await postDirection(req.params.id, text, 'ui');
    if (!rec) return res.status(404).json({ error: 'pipeline not found' });
    res.status(201).json({ id: rec.id });
  } catch (err) {
    if (err && err.code === 'RUN_FINISHED') return res.status(409).json({ error: err.message });
    res.status(500).json({ error: err && err.message ? err.message : String(err) });
  }
});
}
